import type { MetadataRoute } from "next";

/**
 * Minimal robots.txt. The live site's file is generated by Cloudflare (managed AI-crawler rules), which stays in
 * front of the origin and prepends its own block, so only the origin's own rules and the sitemap are declared here.
 */
export default function robots(): MetadataRoute.Robots {
  return {
    rules: [{ userAgent: "*", allow: "/", disallow: ["/api/"] }],
    sitemap: "https://techversantinfotech.com/sitemap.xml",
  };
}
